\label{theorem:HHext} \
\begin{enumerate}
\item If $\deg(\mathcal{C}(G))$, is odd then $\mathbb{L}$ is a field of parametrization.
\item If $\deg(\mathcal{C}(G))$ is even then either $\mathbb{L}$ is a field of parametrization or there exists $\delta\in \overline{\mathbb{L}}$ algebraic over $\mathbb{L}$, with minimal polynomial $t^2-\alpha\in \mathbb{L}[t]$, such that $\mathbb{L}(\delta)$ is a field of parametrization of $\mathcal{C}(G)$.
\end{enumerate}

\label{lem:defVan}
Let $H\in \mathbb{F}[\overline{v}]$, where $\overline{v}$ is a tuple of variables. It holds that
\begin{enumerate}
	\item If $\mathbf{a}^0\in \Omega_{\mathrm{def}(H)}$ then $H(\mathbf{a}^0,\gamma^0,\overline{v})$ is well-defined.
	\item If $\mathbf{a}^0\in \Omega_{\mathrm{nonZ}(H)}$ then $H(\mathbf{a}^0,\gamma^0,\overline{v})\neq 0$.
\end{enumerate}

\label{def-gcd}
Let $f_1,f_2\in \mathbb{F}[u][v]\setminus\{0\}$ for $i\in \{1,2\}$, where $u,v$ are variables. Let $f_i=f_{i}^{*} \, g$, for $i\in \{1,2\}$, where $g=\gcd_{ \mathbb{F}[u][v]}(f_1,f_2)$. Let $A_i\in \mathbb{F}[u]$ be the leading coefficient of $f_i$ w.r.t. $v$ for $i\in \{1,2\}$ and $B\in \mathbb{F}[u]$ the leading coefficient of $g$ w.r.t. $v$. Let $R=\mathrm{res}_{v}(f_{1}^{*},f_{2}^{*})\in \mathbb{F}[u]$.
Let
\[ \begin{array}{l}
\Omega_1:= \Omega_{\mathrm{def}(f_1)} \cap \Omega_{\mathrm{def}(f_2)} \cap  \Omega_{\mathrm{def}(f_{1}^{*})} \cap \Omega_{\mathrm{def}(f_{2}^{*})}\cap \Omega_{\mathrm{def}(g)} \cap \Omega_{\mathrm{def}(R)},\\
\Omega_2:=\Omega_{\mathrm{nonZ}(A_1)} \cap \Omega_{\mathrm{nonZ}(A_2)} \cap \Omega_{\mathrm{nonZ}(B)}\cap \Omega_{\mathrm{nonZ}(R)}.
\end{array}
\]
We define the set
\[ \Omega_{\mathrm{gcd}_{\mathbb{F}[u][v]}(f_1,f_2)}:= \Omega_1\cap \Omega_2. \]

\label{def:gcd-several}
Let $f_1,\ldots,f_r\in \mathbb{F}[v]\setminus\{0\}$, $g=\gcd_{\mathbb{F}[v]}(f_1,\ldots,f_r)$ and $A$ the leading coefficient of $g$ w.r.t. $v$. We consider the polynomial $f_Z:=f_2+f_3Z+\cdots +f_{r} Z^{r-2}\in \mathbb{F}[Z][v]$ where $Z$ is a new variable. We define
\[ \Omega_{\mathrm{gcd}_{\mathbb{F}[v]}(f_1,\ldots,f_r)}:= \Omega_{\mathrm{gcd}_{\mathbb{F}[Z][v]}(f_1,f_Z)} \cap \Omega_{\mathrm{def}(g)}\cap \Omega_{\mathrm{nonZ}(A)}.\]

\label{def:sqfree}
Let $f\in \mathbb{F}[v]\setminus \mathbb{F}$ be squarefree. Let $R$ be the discriminant of $f$ w.r.t. $v$ and let $A$ be the leading coefficient of $f$ w.r.t. $v$. We define the open subset
\[ \Omega_{\mathrm{sqfree}(f)}:=\Omega_{\mathrm{def}(f)} \cap \Omega_{\mathrm{nonZ}(R)}\cap \Omega_{\mathrm{NonZ}(A))}.\]

\label{def:omegaG}
We associate to $G$ the open subset (see~\eqref{eq-G})
$\Omega_G:=\Omega_{\mathrm{def}(G)}\cap \Omega_{\mathrm{nonZ}(g_d)}.$

\label{lem:omegaG} Let $G$ be as above and let $\mathbf{a}^0\in \Omega_G$. Then
\begin{enumerate}
\item $G(\mathbf{a}^0,\gamma^0, x,y)$ is well--defined and $\deg(G(\mathbf{a}^0,\gamma^0, x,y))=\deg(G)$;
\item $G(\mathbf{a}^0,\gamma^0,  x,y)^{h}=G^{h}(\mathbf{a}^0, \gamma^0, x,y,z)$;
\item the partial derivatives of $G^h$, of any order, specialize properly.
\end{enumerate}

\label{rem-Fa}
Given an $\mathbb{F}$--family $\mathcal{F}\in\mathscr{D}(G^h)$ (see~\eqref{eq-SingularLocus}), and $\mathbf{a}^0\in \Omega_{\mathrm{def}(\mathcal{F})}$ (see Def.~\ref{def-defFam}), we observe that, even though $\mathcal{F}$ is irreducible, $\mathcal{F}(\mathbf{a}^0)$ may be reducible. We are interested in working with irreducible specialized families. So, factoring over $\mathbb{K}_{\mathbf{a}^0}$ the defining polynomial of $\mathcal{F}(\mathbf{a}^0)$, the family will be decomposed as
\[ \mathcal{F}(\mathbf{a}^0)=\bigcup_{i\in I} \mathcal{F}_i \]
where $\mathcal{F}_i$ is an irreducible $\mathbb{K}_{\mathbf{a}^0}$--family. We refer to $\mathcal{F}_i$ as the \textit{irreducible subfamilies of $\mathcal{F}(\mathbf{a}^0)$.}
Note that, if $\mathcal{F}(\mathbf{a}^0):=\{(f_1:f_2:f_3)\}_{m}$, each irreducible subfamily is of the form 
$\{ (f_1:f_2:f_3)\}_{m^*}$ where $m^*(t)$ is an irreducible factor of $m(t)$ over  $\mathbb{K}_{\mathbf{a}^0}$.

\label{lem:r-fold}
Let $\mathcal{F}\in \mathscr{D}(G^h)$ (see~\eqref{eq-SingularLocus}) be an irreducible $\mathbb{F}$-family of $r$-fold points of $\mathcal{C}(G^h)$.
If $\mathbf{a}^0\in \Omega_{\mathrm{mult}(\mathcal{F})}$, then every irreducible subfamily of  $\mathcal{F}(\mathbf{a}^0)$ (see Remark~\ref{rem-Fa}) is a $\mathbb{K}_{\mathbf{a}^0}$--family of $r$-fold points of $\mathcal{C}(G^h,\mathbf{a}^0)$.

\label{rem-character} \
\begin{enumerate}
\item Let $\mathcal{F}=\{(f_1:f_2:1)\}_{m} \in \mathscr{D}(G^h)$ (see~\eqref{eq-SingularLocus}) be an irreducible family of affine $r$--fold points; similarly if the family is at infinity. The defining tangent polynomial $T$ is the reduction of
\begin{equation}\label{eq-Tstar}
T^*(\mathbf{a},t,x,y,z)=\sum_{i=0}^{r} \binom{r}{i} \dfrac{\partial^r G}{\partial^i x\,\partial^{r-i} y}(f_1,f_2) (x-f_1z)^i (y-f_2 z)^{r-i}
\end{equation}
modulo $m(t)$.



\item Let $\mathcal{F}$ be as in Def. \ref{def:tangent}. Then $\mathcal{F}$ is a family of ordinary points if and only if $T$ is squarefree over $\mathbb{F}_m$. In the sequel, we assume w.l.o.g. that there is no tangent to $\mathcal{C}_{\mathcal{F}}(G^{h})$ at $\mathcal{F}$ independent of $x$ and that for two different tangents $T_1(\mathbf{a},x,y,z), T_2(\mathbf{a},x,y,z)$ it holds that $T_1(\mathbf{a},x,1,1)\neq T_2(\mathbf{a},x,1,1)$. Note that, if this is not the case, one can apply a linear change over $\mathbb{K}$ (and thus invariant under specializations of the parameters $\mathbf{a}$). Then, the ordinary character of the family is readable from the squarefreeness of $T(\mathbf{a},t,x,1,1)$ over $\mathbb{F}_m$.
\end{enumerate}

\label{lem:ord-fold}
Let $\mathcal{F}\in \mathscr{D}(G^h)$ (see \eqref{eq-SingularLocus}) be an irreducible $\mathbb{F}$-family of ordinary $r$-fold points of $\mathcal{C}(G^h)$.
If $\mathbf{a}^0\in \Omega_{\mathrm{ord}(\mathcal{F})}$, every irreducible subfamily of  $\mathcal{F}(\mathbf{a}^0)$ (see Remark \ref{rem-Fa}) is a $\mathbb{K}_{\mathbf{a}^0}$--family of ordinary $r$-fold points of $\mathcal{C}(G^h,\mathbf{a}^0)$.

\label{cor:mul+ord}
Let $\mathcal{F}\in \mathscr{D}(G^h)$ (see~\eqref{eq-SingularLocus}) be an irreducible $\mathbb{F}$-family of ordinary $r$-fold points of $\mathcal{C}(G^h)$.
If $\mathbf{a}^0\in \Omega_{\mathrm{ord}(\mathcal{F})}$, then all points in $\mathcal{F}(\mathbf{a}^0)$ are ordinary $r$-fold points of $\mathcal{C}(G^h,\mathbf{a}^0)$ and $\#(\mathcal{F})=\#(\mathcal{F}(\mathbf{a}^0))$.

\label{theorem:genus-weak}
Let $\mathbf{a}^0\in \Omega_{\mathrm{singOrd}(F^h)}$. If $\mathcal{C}(F,\mathbf{a}^0)$ is irreducible, then
\[ \mathrm{genus}(\mathcal{C}(F))\geq \mathrm{genus}(\mathcal{C}(F,\mathbf{a}^0)). \]

\label{def-OpenGB}
Let $\mathrm{I}$ be an ideal in $\mathbb{F}[\overline{v}]$, where $\overline{v}$ is tuple of variables, generated by $\mathscr{G}\subset \mathbb{F}[\overline{v}]$. Let $\mathcal{G}$ be a Gr\"obner basis of $\mathscr{G}$ w.r.t. some order. We define   $\Omega_{\mathrm{spGB}(\mathcal{G})}\subset \mathbb{S}$ as a non-empty open subset such that for every $\mathbf{a}^0\in \Omega_{\mathrm{spGB}(\mathcal{G})}$ it holds that
$\{ g(\mathbf{a}^0,\gamma^0,\overline{v}) \,|\, g\in \mathcal{G}\}$ is a Gr\"obner basis, w.r.t. the same order, of the ideal generated by $\{ g(\mathbf{a}^0,\gamma^0,\overline{v}) \,|\, g\in \mathscr{G}\}$ in $\mathbb{K}_{\mathbf{a}^0}[\overline{v}]$.

\label{def:genusOrdAffine} \textsf{(Affine singularities)} 
With the notation introduced above, let \[ \Omega_1=\Omega_{\mathrm{nonZ}(U)} \cap \Omega_{\mathrm{gcd}(f,f_x)}\cap \Omega_{\mathrm{sqfree}(\tilde{f})}, \,\, \,\,\Omega_2=\Omega_{\mathrm{nonZ}(V)} \cap \Omega_{\mathrm{gcd}(g,g_y)}\cap \Omega_{\mathrm{sqfree}(\tilde{g})}
\]
where $U$ and $V$ are the leading coefficients of $f$ and $g$ w.r.t. $x$ and $y$, respectively.
We define the open subset
\[ \Omega_{\mathrm{sing}_a(F)}:=\bigcap_{i=1}^{3} \Omega_{\mathrm{spGB}(\mathcal{G}_i)}  {\bigcap_{q\in \mathcal{G}_1\setminus \{f\}}
\Omega_{\mathrm{nonZ}(W_{q,y})}} {\bigcap_{q\in \mathcal{G}_2\setminus \{g\}}
\Omega_{\mathrm{nonZ}(W_{q,x})}} \cap \Omega_1\cap \Omega_2 \cap \Omega_{\mathrm{sqfree}(A)}\]
where $W_{q,y}$ denotes the leading coefficient of $q$ w.r.t. $y$; similarly with $W_{q,x}$.

\label{def:genusOrdInf} \textsf{(Singularities at infinity)} 
Let $M(\mathbf{a},\gamma,y,z):=F^h(\mathbf{a},\gamma,1,y,z)$, let $U(\mathbf{a},\gamma,t)=\gcd(M(\mathbf{a},\gamma,t,0),M_y(\mathbf{a},\gamma,t,0),M_z(\mathbf{a},\gamma,t,0))$ and $\tilde{U}(\mathbf{a},\gamma,t):=U/\gcd(U,U')$, where $U'$ is the derivative of $U$ w.r.t. $t$.  Let 
$$\Omega_{(0:1:0)}:=\left\{
\begin{array}{cl}
\mathbb{S}  & \text{if $(0:1:0)\in \mathrm{sing}(\mathcal{C}(F^h))$} \\
\Omega_{\mathrm{nonZ}(J(\mathbf{a},\gamma,0,1,0))}
& \text{if $(0:1:0)\notin \mathrm{sing}(\mathcal{C}(F^h))$} \end{array} \right.$$
where $J$ is one the first derivatives of $F^h$ not vanishing at $(0:1:0)$.  We define the open subset  
\[ \Omega_{\mathrm{sing}_\infty(F)}:=\Omega_{\mathrm{gcd}(M(\mathbf{a},\gamma,t,0),M_y(\mathbf{a},\gamma,t,0),M_z(\mathbf{a},\gamma,t,0))} \cap \Omega_{\mathrm{gcd}(U,U')} \cap \Omega_{(0:1:0)}. \]

\label{def:genusOrd}
We define the open subset 
\[ \Omega_{\mathrm{genusOrd}(F^h)}:= \Omega_{\mathrm{singOrd}(F^h)} \cap \Omega_{\mathrm{sing}_a(F)}\cap \Omega_{\mathrm{sing}_\infty(F)}. \]

\label{lem:card-sing}
Let $\mathbf{a}^0\in \Omega_{\mathrm{sing}_a(F)}\cap \Omega_{\mathrm{sing}_\infty(F)}$. Then
\[ \#(\mathrm{sing}(\mathcal{C}(F^h))=\#(\mathrm{sing}(\mathcal{C}(F^h,\mathbf{a}^0)). \]

\label{theorem:genus-strong}
Let $\mathbf{a}^0\in \Omega_{\mathrm{genusOrd}(F^h)}$. If $\mathcal{C}(F,\mathbf{a}^0)$ is irreducible, then
\[ \mathrm{genus}(\mathcal{C}(F))= \mathrm{genus}(\mathcal{C}(F,\mathbf{a}^0)). \]

\label{thm:genusPreservation}
Let $F \in \mathbb{F}[x,y]$ be as in~\eqref{eq-F}, and let $\mathbf{a}^0 \in \Omega_{\mathrm{genus}(F)}$. If $\mathcal{C}(F,\mathbf{a}^0)$ is irreducible, then
\[ \mathrm{genus}(\mathcal{C}(F))= \mathrm{genus}(\mathcal{C}(F,\mathbf{a}^0)). \]

We start recalling that the quadratic transformation defines a birational map (see e.g.~\cite[Chapter V, Section 4.2]{walker}) from the original curve on its quadratic transformed curve (see the precise definition of transformed curve in Step 2 of the blow up at a point in Subsection~\ref{subsec-genus} in the appendix), and that the genus is a birational invariant (see e.g.~\cite[Theorem 7.2.2 or Prop. 8.5.1]{mauro}). Then, since $G^h$ is the quadratic transformation of $F^h$, we have that
\begin{equation}\label{eqq-genus1}
\mathrm{genus}(\mathcal{C}(F^h(\mathbf{a},x,y,z)))=\mathrm{genus}(\mathcal{C}(G^h(\mathbf{a},\gamma^*,x,y,z))).
\end{equation}

Let $\varphi^0$ denote the map $\varphi(\mathbf{a}^0,(\gamma^*)^0,x,y,z)$. Since $\mathbf{a}^0 \in \Omega_{\mathrm{blowup}(F)}$, by Lemma~\ref{lem:specializationBirational}, $\varphi^0$ is birational and, by Lemma~\ref{lemm:biratR}, $G^h(\mathbf{a}^0,(\gamma^*)^0,x,y,z)$ is the quadratic transformation of $F^h(\mathbf{a}^0,\gamma^0,x,y,z)$ via $\varphi^0$. Therefore, using the same argumentation as in~\eqref{eqq-genus1}, on gets
\begin{equation}\label{eqq-genus2}
\mathrm{genus}(\mathcal{C}(F^h(\mathbf{a}^0,\gamma^0,x,y,z)))=\mathrm{genus}(\mathcal{C}(G^h(\mathbf{a}^0,(\gamma^*)^0,x,y,z))).
\end{equation}
Moreover, since $\mathbf{a}^0 \in \Omega_{\mathrm{genusOrd}(G^h)}$, by Theorem~\ref{theorem:genus-strong}, it holds that
\begin{equation}\label{eqq-genus3}
\mathrm{genus}(\mathcal{C}(G^h(\mathbf{a},\gamma^*x,y,z))) = \mathrm{genus}(\mathcal{C}(G^h(\mathbf{a}^0,(\gamma^*)^0,x,y,z))) .
\end{equation}
Now, the proof follows from~\eqref{eqq-genus1}, \eqref{eqq-genus2} and~\eqref{eqq-genus3}.

\label{def:deg1}
Let $F=A_2(\mathbf{a},\gamma)x+A_1(\mathbf{a},\gamma) y+A_0(\mathbf{a},\gamma)\in \mathbb{F}[x,y] \setminus \mathbb{F}$. Since $\mathcal{C}(F)$ is a line, it can be properly parametrized by a polynomial parametrization of the form $\mathcal{P}(\mathbf{a},\gamma,t)=(\lambda_1 t+\lambda_0, \mu_1 t+ \mu_0)\in \mathbb{F}(t)^2\setminus \mathbb{F}^2$. We define the set (see Def.~\ref{def-open1} and~\ref{def:omegaG})
\[ \Omega_{\mathrm{proper}(\mathcal{P})}:= \Omega_{F} \cap \Omega_{\mathrm{def}(\lambda_1 t+\lambda_0)} \cap \Omega_{\mathrm{def}(\mu_1 t+\mu_0)} \cap \left( \Omega_{\mathrm{nonZ}(\lambda_1)} \cup \Omega_{\mathrm{nonZ}(\mu_1)}\right).\]

\label{rem-caseslineal}
With the notation in Proposition~\ref{prop:deg1}, if $\mathbf{a}^0\in \mathbb{S}\setminus  \Omega_{\mathrm{proper}(\mathcal{P})}$, then:
\begin{enumerate}
\item If $\mathbf{a}^0\not\in \Omega_F\setminus  \Omega_{\mathrm{def}(F)}$, it holds that $ F(\mathbf{a}^0,\gamma^0,x,y)=A_0(\mathbf{a}^0,\gamma^0)\in \overline{\mathbb{K}}$, and hence $\mathcal{C}(F,\mathbf{a}^0)$ does not define an affine curve.
\item If $\mathbf{a}^0\not\in \Omega_{\mathrm{def}(\lambda_1 t+\lambda_0)}$ but $\mathbf{a}^0\in \Omega_F$ (similarly if $\mathbf{a}^0\not\in\Omega_{\mathrm{def}(\mu_1 t+\mu_0)}$), the specialization $\mathcal{P}(\mathbf{a}^0,\gamma^0,t)$ is not well--defined even though $\mathcal{C}(F,\mathbf{a}^0)$ is a line. In this case, $\mathcal{C}(F,\mathbf{a}^0)$ is rational and a proper parametrization of the specialized line can be provided.
\item If $\mathbf{a}^0\not\in \left( \Omega_{\mathrm{nonZ}(\lambda_1)} \cup \Omega_{\mathrm{nonZ}(\mu_1)}\right)$ but $\mathbf{a}^0\in \Omega_F\cap \Omega_{\mathrm{def}(\lambda_1 t+\lambda_0)} \cap \Omega_{\mathrm{def}(\mu_1 t+\mu_0)}$, then $\mathcal{P}(\mathbf{a}^0,\gamma^0,t)\in \overline{\mathbb{K}}^2$ and hence it is not a parametrization although $\mathcal{C}(F,\mathbf{a}^0)$ is a line. As in case (2), a polynomial parametrization of the specialized line can be provided.
\end{enumerate}

\label{cases} Let us analyze the behavior of $F$ and/or $\mathcal{P}$ when specializing in $\mathbb{S}\setminus \Omega_{\mathrm{proper}(\mathcal{P})}$.
\begin{enumerate}
\item If $\mathbf{a}^0\in \mathbb{S}\setminus \Omega_{1}$, since $F\in \mathbb{K}[\mathbf{a}][x,y]$ (see \eqref{eq-F}), then $F(\mathbf{a}^0,x,y)$ is always well--defined, and hence, $\deg(F(\mathbf{a}^0,x,y))< \deg(F(\mathbf{a},x,y))$. So, it can happen that either $0<\deg(F(\mathbf{a}^0,x,y))< \deg(F(\mathbf{a},x,y))$, so $\mathcal{C}(F,\mathbf{a}^0)$ is an affine curve; or $0=\deg(F(\mathbf{a}^0,x,y))$, which implies that $\mathcal{C}(F,\mathbf{a}^0)$ is the empty set or $\overline{\mathbb{K}}^2$.
\item If $\mathbf{a}^0\in \mathbb{S}\setminus \Omega_{2}$, then $\mathcal{P}(\mathbf{a}^0,t)$ is not defined, and hence the specialization fails.

\item If $\mathbf{a}^0\in \left(\mathbb{S}\setminus (\Omega_{3}\cap \Omega_{4})\right)\cap \Omega_1\cap \Omega_2$, at least one of the following assertions hold.
\begin{enumerate}
\item $\mathcal{P}(\mathbf{a}^0,t)$ is not proper.
\item $\mathcal{P}(\mathbf{a}^0,t)\in \overline{\mathbb{K}}^2$ and hence, $\mathcal{P}(\mathbf{a}^0,t)$ is not a parametrization.
\item$\mathcal{P}(\mathbf{a}^0,t)$ parametrizes a proper factor of $F(\mathbf{a}^0,x,y)$, that is, $\mathcal{C}(F,\mathbf{a}^0)$ decomposes and one of its components is rational and parametrized by $\mathcal{P}(\mathbf{a}^0,t)$.
\end{enumerate}
\end{enumerate}

Let $\mathcal{P}$ be as in~\eqref{eq-Pa}. If $\mathcal{P}$ is normal, we define the set
