\label{ex-app3} \textsf{Rational solution of functional algebraic equations.} \\
We consider the functional algebraic equation
\begin{equation}\label{eq-funEx}
  x^{2} y^{3} f_{1}^{4}-x^{2} y^{2} f_{2}^{4} f_{3}-2 x \,y^{3} f_{1}^{2} f_{2}+2 x y f_{1} f_{2}^{2} f_{3}^{2}+y^{3} f_{2}^{2}-f_{1}^{2} f_{3}^{3}
=0, \end{equation}
where $\mathbf{f}=(f_1,f_2,f_3):=(\sin(t),\cos(t),\mathrm{e}^{t})$. We associate to \eqref{eq-funEx} the curve $\mathcal{C}(F)$ where
\[ F=x^{2} y^{3} a_{1}^{4}-x^{2} y^{2} a_{2}^{4} a_{3}-2 x \,y^{3} a_{1}^{2} a_{2}+2 x y a_{1} a_{2}^{2} a_{3}^{2}+y^{3} a_{2}^{2}-a_{1}^{2} a_{3}^{3}. \]
It holds that $\mathrm{genus}(\mathcal{C}(F))=0$ and that a proper parametrization is 
\begin{equation}\label{eq-P-ex}
 \mathcal{P}(\mathbf{a},W)=\left(\frac{W^{3} a_{1}+a_{2}}{W a_{2}^{2}+a_{1}^{2}}, 
\frac{a_{3}}{W^{2}}\right). 
\end{equation}
The open subset in Def. \ref{def-omega} turns to be
\[ \Omega_{\mathrm{proper}(\mathcal{P})}= \overline{\mathbb{C}(\mathbf{f})}^3\setminus \mathbb{V}_{\overline{\mathbb{C}(\mathbf{f})}}\left(a_{1} a_{2}  \left(a_{1}-a_{2}\right) \left(a_{1}^{6}+a_{1}^{5} a_{2}+a_{1}^{4} a_{2}^{2}+a_{1}^{3} a_{2}^{3}+a_{1}^{2} a_{2}^{4}+a_{1} a_{2}^{5}+a_{2}^{6}\right) a_{3} \right). \]
Since $\mathbf{f}\in \Omega_{\mathrm{proper}(\mathcal{P})}$, by Theorem \ref{thrm:genus0general}, we have that
\begin{equation}\label{eq-solApp} \left\{ x=\frac{W^{3} \sin \! \left(t \right)+\cos \! \left(t \right)}{W \left(\cos^{2}\left(t \right)\right)+\sin^{2}\left(t \right)}
, y=\frac{{\mathrm e}^{t}}{W^{2}}
\right\},
\end{equation}
for every $W\in \overline{\mathbb{C}(\mathbf{f})}$ such that~\eqref{eq-solApp} is well--defined, is a rational solution of~\eqref{eq-funEx}. In fact, the last statement holds more generally for every $W\in \overline{\mathrm{Mer}(\mathbb{C})}$.

\label{def-family}
The set $\mathcal{F}=\{ (f_1(\alpha):f_2(\alpha): f_3(\alpha))\,|\, m(\alpha)=0 \}\subset \mathbb{P}^2(\overline{K})$ is called a
\textit{$K$--conjugate family of points}, or for short \textit{$K$-family of points}, if
\begin{enumerate}
\item $f_1,f_2,f_3,m\in K[t]$ and $gcd(f_1,f_2,f_3,m)=1$,
\item at least one of the polynomials $f_i$ is not zero,
\item  $\deg_t(m)>0$ and $m$ is squarefree.                  


\end{enumerate}
The family is represented as $$\mathcal{F}:=\{ (f_1:f_2: f_3)\}_{m}$$ and $m(t)$ is called the \textit{defining polynomial of $\mathcal{F}$}.  If $m(t)$ is irreducible over $K$, we say that $\mathcal{F}$ is \textit{irreducible}. We say that $\mathcal{F}:=\{ (f_1:f_2: f_3)\}_{m}$ is in \textit{canonical form} if $f_1,f_2,f_3$ are reduced modulo $m(t)$. In this paper, we will always assume that families are irreducible and expressed in canonical form.

\label{rem-fam}\
\begin{enumerate}
\item A single point $(a:b:c)\in \mathbb{P}^2(K)$ can be seen as the  $K$-family   $\{(a:b:c)\}_{t}.$
\item Factoring the defining polynomial $m(t)$ over $K$, every family decomposes as a finite union of irreducible families.  
\item For $H\in K[x,y,z]$ and $\mathcal{F}:=\{ (f_1 :f_2 : f_3 )\}_{m )}$ irreducible, $H(f_1(t),f_2(t),f_3(t))\neq 0$ mod $m(t)$ iff $H$ does not vanish at any point in the family $\mathcal{F}$.









\end{enumerate}

\label{def-stand-decomp}
A decomposition of the singular locus of the irreducible curve $\mathcal{C}(G^h)$ 
as a finite union of irreducible families of $K$-points, such that in each family the multiplicity and the singularity character is preserved, is called \textit{a $K$--standard decomposition of the singular locus of $\mathcal{C}(G^h)$} (see Remark~\ref{rem-standard-decomp-final} below).

\label{def-regular}
We say that the affine plane curve $\mathcal{C}(G)$ is in \textit{regular position} w.r.t. $x$ if
\begin{enumerate}
\item the coefficient of $y^{\deg(G)}$ in $G$ is a non-zero constant; and
\item $G(a,b_i)=G_x(a,b_i)=0$ with $i\in \{1,2\}$ implies that $b_1=b_2$.
\end{enumerate}

\label{rem-standard-decomp-final}
Throughout the paper, we will use the $K$-standard decomposition achieved by means of the previous reasoning; we denote it as $\mathscr{D}(G^h))$. We observe that  
\begin{equation}\label{eq-SingularLocusApp}
\mathscr{D}(G^h):=\bigcup_{m(t)\in \mathcal{A}_a} \{(f_{1,m}:f_{2,m}:1)\}_{m} \, \cup \,  \bigcup_{m\in \mathcal{A}_{\infty}} \{(L_{1,m}:L_{2,m}:0)\}_{m}
\end{equation}
where $f_{i,m}(t),m(t)\in K[t]$, $L_{i,m}(t)\in \mathbb{K}[t]$  with $\deg(L_{i,m}(t))\leq 1$, $\gcd(L_{1,m}(t),L_{2,m}(t))=1$, and  $\mathcal{A}_a$ and $\mathcal{A}_{\infty}$ are finite sets of irreducible polynomials in $K[t]$.

